   100	/**
   101	 * Fetch events from Kulturhuset Elasticsearch API
   102	 * @param {Object} options - Options (limit, etc.)
   103	 * @returns {Promise<Object[]>} - Array of events
   104	 */
   105	export async function fetchKulturhusetEvents(options = {}) {
   106	  const { limit = 20, page = 0 } = options;
   107	  
   108	  const query = {
   109	    size: limit,
   110	    from: page * limit,
   111	    query: {
   112	      bool: {
   113	        must: [
   114	          {
   115	            range: {
   116	              tixStartDate: {
   117	                gte: 'now',  // Only future events
   118	              },
   119	            },
   120	          },
   121	        ],
   122	      },
   123	    },
   124	    sort: [
   125	      { tixStartDate: { order: 'asc' } },
   126	    ],
   127	  };
   128	  
   129	  try {
   130	    const response = await fetch(ELASTIC_SEARCH_URL + '/_search', {
   131	      method: 'POST',
   132	      headers: {
   133	        'Content-Type': 'application/json',
   134	        'User-Agent': 'EventPulse/1.0',
   135	      },
   136	      body: JSON.stringify(query),
   137	    });
   138	    
   139	    if (!response.ok) {
   140	      throw new Error(`Kulturhuset API error: ${response.status}`);
   141	    }
   142	    
   143	    const data = await response.json();
   144	    
   145	    if (!data.hits || !data.hits.hits) {
   146	      return [];
   147	    }
   148	    
   149	    return data.hits.hits.map(mapKulturhusetEvent);
   150	  } catch (error) {
   151	    console.error('Kulturhuset scraper error:', error);
   152	    throw error;
   153	  }
   154	}
